static uint64_t fnv_bytes(const uint8_t *p, size_t n) {
    uint64_t h = 1469598103934665603ull;
    for (size_t i = 0; i < n; i++) {
        h ^= p[i];
        h *= 1099511628211ull;
    }
    return h;
}

#define BIG_FNV 0x558543800aa16137ull

static const char *BIG_A =
    "The quick brown fox jumps over the lazy dog. ";

int main(void) {
    int fails = 0;
    static uint8_t buf[65536 + 64];
    for (size_t c = 0; c < sizeof CASES / sizeof CASES[0]; c++) {
        size_t n = tsimd_spm_normalize((const uint8_t *)CASES[c].in,
                                       CASES[c].in_len, buf, sizeof buf, 1, 1);
        if (n == (size_t)-1) {
            fprintf(stderr, "case %zu: normalize failed\n", c);
            fails++;
            continue;
        }
        if (n != CASES[c].out_len ||
            memcmp(buf, CASES[c].out, CASES[c].out_len) != 0) {
            fprintf(stderr, "case %zu: got %zu bytes", c, n);
            for (size_t k = 0; k < n && k < 40; k++)
                fprintf(stderr, " %02x", buf[k]);
            fprintf(stderr, "\n        want %zu bytes", CASES[c].out_len);
            for (size_t k = 0; k < CASES[c].out_len && k < 40; k++)
                fprintf(stderr, " %02x", (unsigned char)CASES[c].out[k]);
            fprintf(stderr, "\n");
            fails++;
        }
        if (CASES[c].in_len > 0) {
            size_t small = tsimd_spm_normalize((const uint8_t *)CASES[c].in,
                                               CASES[c].in_len, buf, 4, 1, 1);
            if (CASES[c].out_len > 4 && small != (size_t)-1) {
                fprintf(stderr, "case %zu: a short cap must fail\n", c);
                fails++;
            }
        }
    }
    size_t blen = 0;
    for (int r = 0; r < 100; r++) {
        memcpy(buf + blen, BIG_A, 45);
        blen += 45;
    }
    for (int r = 0; r < 20; r++) {
        memset(buf + blen, 'a', 100);
        blen += 100;
        buf[blen++] = ' ';
        buf[blen++] = ' ';
    }
    static uint8_t nb[65536 + 64];
    size_t nn = tsimd_spm_normalize(buf, blen, nb, sizeof nb, 1, 1);
    if (nn == (size_t)-1 || fnv_bytes(nb, nn) != BIG_FNV) {
        fprintf(stderr, "big pattern: got %zu bytes fnv %016llx want %016llx\n",
                nn, (unsigned long long)(nn == (size_t)-1 ? 0 : fnv_bytes(nb, nn)),
                (unsigned long long)BIG_FNV);
        fails++;
    }
    if (fails) {
        fprintf(stderr, "%d spm normalize checks FAILED\n", fails);
        return 1;
    }
    printf("test_spm_normalize: %zu cases and the %zu byte pattern match the "
           "reference normalizer\n",
           sizeof CASES / sizeof CASES[0], blen);
    return 0;
}
